<?php

namespace App\Console\Commands;

use App\Models\SchoolInfo;
use Illuminate\Console\Command;
use Illuminate\Support\Facades\Http;

class SyncSchoolSettings extends Command
{
    protected $signature = 'sync:settings {--dry : Sirf dikhao, save mat karo} {--force : Local ki bhari hui values bhi overwrite karo}';

        protected $description = 'Live Supabase school_info ki values local Laravel settings mein copy karo';

            public function handle(): int
                {
                        $url = rtrim((string) env('SUPABASE_URL'), '/');
                                $key = (string) env('SUPABASE_SERVICE_KEY');

                                        if ($url === '' || $key === '') {
                                                    $this->error('SUPABASE_URL ya SUPABASE_SERVICE_KEY .env mein nahi hai.');
                                                                return self::FAILURE;
                                                                        }

                                                                                $response = Http::withHeaders([
                                                                                            'apikey' => $key,
                                                                                                        'Authorization' => 'Bearer ' . $key,
                                                                                                                ])->get($url . '/rest/v1/school_info', ['select' => '*', 'limit' => 1]);

                                                                                                                        $rows = $response->successful() ? $response->json() : [];
                                                                                                                                if (empty($rows)) {
                                                                                                                                            $this->error('Live school_info se data nahi mila (HTTP ' . $response->status() . ').');
                                                                                                                                                        return self::FAILURE;
                                                                                                                                                                }

                                                                                                                                                                        $local = SchoolInfo::query()->first();
                                                                                                                                                                                if (!$local) {
                                                                                                                                                                                            $this->error('Local school_info row nahi mili.');
                                                                                                                                                                                                        return self::FAILURE;
                                                                                                                                                                                                                }

                                                                                                                                                                                                                        $skip = ['id', 'created_at', 'updated_at'];
                                                                                                                                                                                                                                $changes = [];

                                                                                                                                                                                                                                        foreach ($rows[0] as $field => $value) {
                                                                                                                                                                                                                                                    if (in_array($field, $skip, true)) {
                                                                                                                                                                                                                                                                    continue;
                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                            if (!array_key_exists($field, $local->getAttributes())) {
                                                                                                                                                                                                                                                                                                            continue;
                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                    $value = is_string($value) ? trim($value) : $value;
                                                                                                                                                                                                                                                                                                                                                $current = $local->{$field};
                                                                                                                                                                                                                                                                                                                                                            $current = is_string($current) ? trim($current) : $current;
                                                                                                                                                                                                                                                                                                                                                                        $empty = $current === null || $current === '';

                                                                                                                                                                                                                                                                                                                                                                                    if ($value === null || $value === '') {
                                                                                                                                                                                                                                                                                                                                                                                                    continue;
                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                            if (!$empty && !$this->option('force')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                            continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if ((string) $current === (string) $value) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $changes[$field] = $value;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $this->line(sprintf('%-25s "%s" -> "%s"', $field, $current, $value));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (empty($changes)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $this->info('Koi naya change nahi hai.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return self::SUCCESS;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if ($this->option('dry')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $this->warn(count($changes) . ' field(s) badal sakti hain. --dry hata kar chalayein to save hoga.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return self::SUCCESS;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $local->forceFill($changes)->save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $this->info(count($changes) . ' field(s) update ho gayi.');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return self::SUCCESS;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            git pull && git apply gr-import-upload.patch && git rm -q -f gr-import-upload.patch && git add -A && git commit -m "GR register CSV upload" && git push